const text = $input.item.json.text || '';
const email = $input.item.json.from || '';
const subject = $input.item.json.subject || '';

// Extract date patterns (e.g. 2026-05-14 or May 14, 2026)
const dateMatch = text.match(/\b(\d{4}-\d{2}-\d{2}|[A-Z][a-z]+ \d{1,2},? \d{4})\b/);

// Extract court file numbers (Ontario format: CV-24-12345 or court file #)
const fileNumMatch = text.match(/(?:court file|file no\.?|CV|CL|SC|OCJ)[\s#:\-]*(\d{2,}-[\w\-]+|\d{5,})/i);

// Detect document type from keywords
const docType = /notice of motion/i.test(text) ? 'Notice of Motion'
  : /statement of claim/i.test(text) ? 'Statement of Claim'
  : /affidavit/i.test(text) ? 'Affidavit'
  : /response to/i.test(text) ? 'Response'
  : /factum/i.test(text) ? 'Factum'
  : /demand letter/i.test(text) ? 'Demand Letter'
  : 'Court Document';

return [{
  json: {
    rawText: text,
    fromEmail: email,
    emailSubject: subject,
    documentType: docType,
    hearingDate: dateMatch ? dateMatch[0] : 'Not found',
    courtFileNumber: fileNumMatch ? fileNumMatch[0] : 'Not found',
    charCount: text.length
  }
}];
